import json

async def execute(self, inputs):
    action      = str(inputs.get('action') or self.parameters.get('action', 'stats') or 'stats')
    workflow    = str(inputs.get('workflow') or self.parameters.get('workflow', '') or '')
    environment = str(inputs.get('environment') or self.parameters.get('environment', '') or '')
    score       = float(inputs.get('score') or self.parameters.get('score', 0.0) or 0.0)
    failure_type = str(inputs.get('failure_type') or self.parameters.get('failure_type', '') or '')

    try:
        from src.runtime.studio.studio_knowledge import get_studio_knowledge_db
        sk = get_studio_knowledge_db()

        if action == 'record_success' and workflow:
            sk.record_success(workflow=workflow, environment=environment, score=score)
            result = {'status': 'recorded', 'type': 'success', 'workflow': workflow}
            self.log_info(f'[StudioKnowledge] Recorded success: {workflow!r}')
        elif action == 'record_failure' and workflow:
            sk.record_failure(workflow=workflow, environment=environment, failure_type=failure_type)
            result = {'status': 'recorded', 'type': 'failure', 'workflow': workflow}
            self.log_info(f'[StudioKnowledge] Recorded failure: {workflow!r}')
        elif action == 'record_pattern' and workflow:
            sk.record_pattern(pattern_id=workflow, pattern_type='scene_pattern', environment=environment, outcome='success')
            result = {'status': 'recorded', 'type': 'pattern', 'pattern_id': workflow}
        elif action == 'successes':
            result = {'successes': sk.get_studio_successes(environment=environment or None, limit=20)}
        elif action == 'failures':
            result = {'failures': sk.get_studio_failures(environment=environment or None, limit=20)}
        elif action == 'patterns':
            result = {'patterns': sk.get_studio_patterns(environment=environment or None, limit=20)}
        else:
            result = sk.get_studio_statistics()

        stats = sk.get_studio_statistics()
        return {
            'result_json':   json.dumps(result, sort_keys=True),
            'success_count': stats.get('total_successes', 0),
            'failure_count': stats.get('total_failures', 0),
            'success_rate':  stats.get('success_rate', 0.0),
            'exec_out':      True,
        }
    except Exception as e:
        self.log_error(f'[StudioKnowledge] {e}')
        return {
            'result_json':   json.dumps({'error': str(e)}),
            'success_count': 0,
            'failure_count': 0,
            'success_rate':  0.0,
            'exec_out':      True,
        }

def register_node():
    from src.nodes.base import BaseNode
    class Hou_Mcp_Studio_Knowledge(BaseNode):
        name = 'hou_mcp_studio_knowledge'
        async def execute(self, inputs):
            return await execute(self, inputs)
    return Hou_Mcp_Studio_Knowledge
